{"code": "import tensorflow as tf
from PIL import Image
import pathlib

data_dir = pathlib.Path("data_small/Training_Handwritten_marathi_Character_Fusion/Data_set")

# Try to load each image and identify problematic ones
problematic_files = []
valid_files = []

for subdir in data_dir.iterdir():
    if subdir.is_dir():
        for file in subdir.iterdir():
            if file.is_file() and file.suffix in ['.jpg', '.JPG', '.png', '.PNG']:
                try:
                    # Try to open with PIL first
                    with Image.open(file) as img:
                        img.verify()

                    # Also try with TensorFlow
                    img = tf.io.read_file(str(file))
                    img = tf.image.decode_image(img)

                    valid_files.append(file)
                except Exception as e:
                    problematic_files.append((file, str(e)))

print(f"Valid files: {len(valid_files)}")
print(f"Problematic files: {len(problematic_files)}")
if problematic_files:
    print("\nProblematic files:")
    for f, err in problematic_files:
        print(f"  {f}: {err}")"}

